// RULES CHECK: simple, sure checks before any AI is used.
const msg = $json.body || $json;   // webhook puts data in "body"; sample message doesn't
const text = `${msg.subject || ''} ${msg.text || ''}`.trim();
const lower = text.toLowerCase();

// Words that always need a human, fast (from routing_rules.json)
const urgentWords = ['consumer court', 'legal notice', 'lawyer', 'police', 'fraud',
  'cheat', 'injury', 'injured', 'burst', 'flooded', 'flood', 'refund my money'];

// Child or health questions: AI can draft, but a human must check before sending
const draftWords = ['baby', 'child', 'kid', 'year old', 'pregnant', 'allergy',
  'eczema', 'rash', 'doctor'];

// Find an order ID like WS100102
const orderMatch = text.toUpperCase().match(/WS\d{6}/);

// Where did they buy it? (returns and warranty rules depend on this)
let purchaseChannel = 'unknown';
if (lower.includes('amazon')) purchaseChannel = 'amazon';
else if (lower.includes('flipkart')) purchaseChannel = 'flipkart';
else if (lower.includes('website') || orderMatch) purchaseChannel = 'website';

return {
  json: {
    msg_id: msg.msg_id,
    channel: msg.channel,
    text: text,
    order_id: orderMatch ? orderMatch[0] : '',
    purchase_channel: purchaseChannel,
    urgent_word: urgentWords.find(w => lower.includes(w)) || '',
    draft_word: draftWords.find(w => lower.includes(w)) || '',
    too_short: text.replace(/[^a-z0-9]/gi, '').length < 3,
  },
};

