// DECIDE ROUTE: plain rules decide what happens. The AI never decides this.
const ai = $json.output;                        // AI labels + draft reply
const rc = $('Rules Check').first().json;       // results of the simple checks
const order = $('Find Order').first().json;     // order row (empty if none)

// Normal route for each message type (same as routing_rules.json)
const BASE = {
  fit_compatibility: 'AUTO_SEND', installation_help: 'AUTO_SEND',
  low_flow_clogging: 'AUTO_SEND', leak: 'AUTO_SEND', cartridge_question: 'AUTO_SEND',
  effectiveness_tds: 'AUTO_SEND', product_recommendation: 'AUTO_SEND',
  order_status: 'AUTO_SEND', spare_part_request: 'DRAFT', other: 'DRAFT',
  damaged_defective: 'HUMAN', warranty_claim: 'HUMAN', return_refund: 'HUMAN',
  escalation: 'URGENT',
};
const LEVEL = { AUTO_SEND: 0, DRAFT: 1, HUMAN: 2, URGENT: 3 };

let route = BASE[ai.intent] || 'DRAFT';
const why = [`${ai.intent} is ${route} by default`];

// A safety check can only make the route MORE careful, never less.
function raise(newRoute, reason) {
  if (LEVEL[newRoute] > LEVEL[route]) { route = newRoute; why.push(reason); }
}

if (rc.urgent_word) raise('URGENT', `danger word: "${rc.urgent_word}"`);
if (rc.too_short) raise('DRAFT', 'message too short to understand');
if (ai.mood === 'angry') raise('HUMAN', 'customer is angry');
if (rc.draft_word) raise('DRAFT', `child/health word: "${rc.draft_word}"`);
if (ai.confidence < 0.8) raise('DRAFT', `AI not sure (${ai.confidence})`);
if (ai.uses_conflict_fact) raise('DRAFT', 'reply uses a [CONFLICT] fact');

// Order checks
const today = new Date().toISOString().slice(0, 10);
if (ai.intent === 'order_status' && rc.order_id) {
  if (!order.order_id) raise('HUMAN', `order ${rc.order_id} not found`);
  else if (order.status !== 'delivered' && order.expected_delivery < today)
    raise('HUMAN', `order ${rc.order_id} is late`);
}

return {
  json: {
    time: new Date().toISOString(),
    msg_id: rc.msg_id,
    channel: rc.channel,
    text: rc.text,
    intent: ai.intent,
    confidence: ai.confidence,
    mood: ai.mood,
    language: ai.language,
    route: route,
    why: why.join('; '),
    reply: ai.reply,
    kb_used: (ai.kb_used || []).join(', '),
    missing_info: (ai.missing_info || []).join(', '),
    order_id: rc.order_id,
    summary: ai.summary,
  },
};

// AI FAILED: if Gemini is down or busy, the message still reaches a human.
const rc = $('Rules Check').first().json;
const err = String($json.error?.message || $json.error || 'unknown error').slice(0, 120);
return {
  json: {
    time: new Date().toISOString(),
    msg_id: rc.msg_id, channel: rc.channel, text: rc.text,
    intent: 'unknown', confidence: 0, mood: '', language: '',
    route: rc.urgent_word ? 'URGENT' : 'HUMAN',
    why: `AI unavailable (${err}) - sent to a person`,
    reply: '', kb_used: '', missing_info: '', order_id: rc.order_id, summary: '',
  },
};
